            var score = this._composite(state);
            ds.performance = { overallScore: score };
            out.overallScore = score;
            out.score = score;
            out.roundScore = rs.score;
            out.profit = ds.last.profit;
            out.cash = ds.last.cash;
            out.moros = ds.last.moros;
            out.docs = ds.last.docs;
            out.pmc = ds.last.pmc;
            out.sales = ds.last.sales;
            if (period >= state.maxPeriods) { ds.finished = true; }
            var self = this;
            var nextP = (state.domainState && state.domainState.finished) ? state.currentPeriod : state.currentPeriod + 1;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state, nextP); }, 300);
            return out;
        }

        _flat(state, upto) {
            var d = (state && state.decisions) || {};
            var out = {};
            var p, k;
            for (p = 1; p <= upto; p++) {
                var r = d['round' + p];
                if (r) { for (k in r) { if (Object.prototype.hasOwnProperty.call(r, k)) { out[k] = r[k]; } } }
            }
            return out;
        }

        _active(dec, k, g) {
            if (this.ROUND_OF[g] <= k) {
                var v = dec[g];
                return (v === undefined || v === null) ? this.DEFAULTS[g] : v;
            }
            return this.REF[g];
        }

        _at(a, g, m) {
            return (m >= this.START[g]) ? a[g] : this.REF[g];
        }

        _event(dec, k) {
            var c = this.C;
            var a = {};
            var j, m, z;
            for (j = 0; j < this.KEYS.length; j++) { a[this.KEYS[j]] = this._active(dec, k, this.KEYS[j]); }
            var war = (k >= 4);
            var mo = war ? this.MORO[a.moro4] : this.MORO[this.REF.moro4];
            var ci = war ? this.CIERRE[a.cierre4] : this.CIERRE[this.REF.cierre4];
            var buy = this.BUY[a.compras1];
            var camp = (a.compras1 === 'campana');
            var ax = this.AUX[a.aux3];
            var fc = [];
            for (m = 1; m <= 12; m++) {
                var pf = this.PRICE[this._at(a, 'precio1', m)];
                fc.push(c.B * c.SEAS[m - 1] * pf[0] * pf[1] * this.TERMS[this._at(a, 'cobro2', m)][0]);
            }
            var coll = [], pays = [];
            for (z = 0; z < 20; z++) { coll.push(0.0); pays.push(0.0); }
            coll[1] = c.AR0[0];
            coll[2] = c.AR0[1];
            pays[1] = c.AP0;
            var cash = c.CASH0, cmin = cash;
            var sales = 0.0, cogsT = 0.0, lost = 0.0, errVal = 0.0, stuck = 0.0, bad = 0.0, emerg = 0.0, late = 0.0;
            var staff = 0.0, rework = 0.0, hold = 0.0, acUnpaid = 0.0, stock = 0.0, loadmax = 0.0, backlog = 0.0;
            var ePrev = c.E0;
            for (m = 1; m <= 12; m++) {
                var pr = this.PRICE[this._at(a, 'precio1', m)];
                var te = this.TERMS[this._at(a, 'cobro2', m)];
                var pa = this.PAY[this._at(a, 'pago2', m)];
                var au = this.AUX[this._at(a, 'aux3', m)];
                var dc = this.DOC[this._at(a, 'doc3', m)];
                var acf = (war && m >= 11) ? mo[2] : 1.0;
                var mix = 1.0 - c.ACAD + c.ACAD * acf;
                var D = c.B * c.SEAS[m - 1] * pr[1] * te[0] * (1.0 - c.CHURN * ePrev) * mix;
                var sold = D * buy[1];
                lost += D - sold;
                var rev = sold * pr[0];
                var acad = rev * c.ACAD * acf / mix;
                var on = (m >= 7) && (au[2] === 0 || m === 9 || m === 10);
                var cap = c.CAP + (on ? au[0] : 0.0);
                var sc = on ? au[1] : 0.0;
                var load = (rev / c.ORDER + c.PO_W * buy[2]) * dc[1] / cap;
                loadmax = Math.max(loadmax, load);
                var bl = this._clamp((load - 1.0) / load, 0.0, c.BL_MAX);
                var fe = dc[0] + (1.0 - dc[0]) * this._clamp((load - 1.0) / c.SKIP, 0.0, 1.0);
                var e = c.E0 * (1.0 + c.KOV * Math.max(load - c.L0, 0.0)) * fe + pr[2];
                if (m >= 10) { e = e * ci[0]; }
                e = this._clamp(e, 0.0, 0.5);
                ePrev = e;
                var ev = rev * e;
                errVal += ev;
                var rw = ev / c.ORDER * c.REWORK;
                rework += rw;
                staff += sc;
                backlog += rev * bl;
                var norm = rev;
                if (war && m >= 9) {
                    if (m >= 11 && mo[4] === 1) {
                        coll[m] += acad;
                        norm = rev - acad;
                    } else if (m >= 11 && mo[3] === 1) {
                        norm = rev;
                    } else {
                        norm = rev - acad;
                        acUnpaid += acad;
                    }
                }
                var b = norm * te[2] * ((m >= 7) ? au[4] : 1.0);
                bad += b;
                var good = norm - b;
                var er = good * e;
                var st = er * c.STUCK * ((m >= 7) ? au[3] : 1.0);
                stuck += st;
                var p = 1.0 - (1.0 - dc[2]) * (1.0 - bl);
                coll[m + te[1]] += (good - er) * (1.0 - p);
                coll[m + te[1] + 1] += (good - er) * p;
                coll[m + te[1] + 1] += (er - st) * (1.0 - p);
                coll[m + te[1] + 2] += (er - st) * p;
                var lag = buy[3] ? pa[0] : 0;
                var cf = buy[3] ? pa[1] : 1.0;
                var cogs = sold * buy[0] * cf;
                cogsT += cogs;
                var lt = 0.0;
                var hm = 0.0;
                if (camp) {
                    if (m === 1 || m === 7) {
                        var lotBase = 0.0;
                        for (z = m - 1; z < m + 5; z++) { lotBase += fc[z]; }
                        var lot = lotBase * buy[0] * c.SAFETY;
                        stock += lot;
                        pays[m + lag] += lot * cf;
                        lt = buy[3] ? (lot * cf * pa[2] * lag + pa[3]) : 0.0;
                    }
                    stock -= sold * buy[0];
                    hm = Math.max(stock, 0.0) * c.HOLD;
                } else {
                    pays[m + lag] += cogs;
                    lt = buy[3] ? (cogs * pa[2] * lag + pa[3] * buy[2]) : 0.0;
                }
                late += lt;
                hold += hm;
                sales += rev;
                cash += coll[m] - pays[m] - c.OVER - sc - hm - rw - lt;
                if (war && m === 10) {
                    cash -= mo[5] + ci[2] * ax[5] + ci[3];
                }
                if (war && m === mo[1]) {
                    cash += acUnpaid * mo[0] * ((a.moro4 === 'quita') ? (1.0 - c.QUITA) : 1.0);
                }
                if (war && m === 12 && ci[1] === 1) {
                    cash += stuck;
                }
                if (cash < 0) {
                    var ee = -cash * c.EMERG / 12.0;
                    emerg += ee;
                    cash -= ee;
                }
                cmin = Math.min(cmin, cash);
            }
            var obs = camp ? Math.max(stock, 0.0) * c.OBSOL : 0.0;
            var rel = (war && ci[1] === 1) ? stuck : 0.0;
            var stuckEnd = stuck - rel;
            var acRec = war ? acUnpaid * mo[0] : 0.0;
            var acOpen = acUnpaid - acRec;
            var quita = (war && a.moro4 === 'quita') ? acRec * c.QUITA : 0.0;
            var xbad = war ? c.B * (c.SEAS[9] + c.SEAS[10] + c.SEAS[11]) * mo[6] : 0.0;
            var one = war ? (mo[5] + ci[2] * ax[5] + ci[3]) : 0.0;
            var prof = sales - cogsT - 12 * c.OVER - staff - rework - errVal * c.ELOSS - bad - xbad - hold - obs - late
                - emerg - one - quita - c.PROV * acOpen;
            var tax = (prof > 0) ? c.TAX * prof : 0.0;
            var net = prof - tax;
            var arEnd = stuckEnd + acOpen;
            for (z = 13; z < 20; z++) { arEnd += coll[z]; }
            var moros = 100.0 * (bad + xbad + stuckEnd + acOpen) / sales;
            var docs = 100.0 * (1.0 - errVal / sales);
            var pmc = 365.0 * arEnd / sales;
            var hard = 0;
            for (j = 0; j < this.HARD.length; j++) {
                var gk = this.HARD[j][0];
                if (a[gk] === this.HARD[j][1] && k >= this.ROUND_OF[gk]) { hard += 1; }
            }
            return { k: k, a: a, sales: sales, net: net, prof: prof, cash: cash, cmin: cmin, moros: moros, docs: docs, pmc: pmc,
                     lost: lost, err: errVal, stuck: stuckEnd, bad: bad + xbad, emerg: emerg, late: late, hold: hold, obs: obs,
                     ar: arEnd, acOpen: acOpen, loadmax: loadmax, backlog: backlog, hard: hard };
        }

        _components(r) {
            var c = this.C;
            return [this._clamp((r.net - c.P_LO) / (c.P_HI - c.P_LO), 0, 1),
                    this._clamp((r.cash - c.C_LO) / (c.C_HI - c.C_LO), 0, 1),
                    this._clamp((c.M_HI - r.moros) / (c.M_HI - c.M_LO), 0, 1),
                    this._clamp((r.docs - c.D_LO) / (c.D_HI - c.D_LO), 0, 1),
                    this._clamp((c.K_HI - r.pmc) / (c.K_HI - c.K_LO), 0, 1),
                    this._clamp((r.sales - c.S_LO) / (c.S_HI - c.S_LO), 0, 1)];
        }

        _roundScore(state, period) {
            var c = this.C;
            var m = this._event(this._flat(state, period), period);
            var comps = this._components(m);
            var w = [c.W_P, c.W_C, c.W_M, c.W_D, c.W_K, c.W_S];
            var tw = 0, num = 0, i;
            for (i = 0; i < 6; i++) { tw += w[i]; num += w[i] * comps[i]; }
            var score = this._clamp(100.0 * num / tw, 0, 100);
            if (m.hard > 0) {
                score = Math.min(score, c.CAP1 - c.CAP_STEP * (m.hard - 1));
            }
            return { score: this._jsround(score), m: m };
        }

        _completed(state) {
            var d = (state && state.decisions) || {};
            var n = 0;
            while (n < this.ROUNDS.length && d['round' + (n + 1)]) { n += 1; }
            return n;
        }

        _composite(state) {
            var n = this._completed(state);
            if (n === 0) { return 0; }
            var w = this.C.ROUND_WEIGHTS;
            var num = 0, den = 0, p;
            for (p = 1; p <= n; p++) {
                var r = this._roundScore(state, p);
                num += w[p - 1] * r.score;
                den += w[p - 1];
            }
            return this._clamp(this._jsround(num / den), 0, 100);
        }

        _verdictKey(score) {
            if (score >= this.C.THRESH_EXCELLENT) { return 'verdict_excellent'; }
            if (score >= this.C.THRESH_GOOD) { return 'verdict_good'; }
            if (score >= this.C.THRESH_DEVELOPING) { return 'verdict_developing'; }
            return 'verdict_beginner';
        }

        _jsround(x) {
            return (x >= 0) ? Math.floor(x + 0.5) : Math.ceil(x - 0.5);
        }

        _clamp(x, lo, hi) {
            if (x < lo) { return lo; }
            if (x > hi) { return hi; }
            return x;
        }

        _str(id, fallback) {
            var el = document.getElementById(id);
            return (el && el.value) ? el.value : fallback;
        }

        _t(key) {
            var sim = window.mySimulation;
            return (sim && sim.t) ? sim.t(key) : key;
        }

        _lang() {
            var sim = window.mySimulation;
            return (sim && sim.language) ? sim.language : 'es';
        }

        _fmtInt(n) {
            var v = Math.round(Math.abs(n));
            var s = String(v);
            var sep = (this._lang() === 'en') ? ',' : '.';
            var out = '';
            var i, k = 0;
            for (i = s.length - 1; i >= 0; i--) {
                out = s.charAt(i) + out;
                k += 1;
                if (k % 3 === 0 && i > 0) { out = sep + out; }
            }
            return (n < 0 && v > 0 ? '-' : '') + out;
        }

        _fmtDec(n) {
            var v = Math.round(n * 10) / 10;
            var whole = Math.floor(Math.abs(v));
            var dec = Math.round((Math.abs(v) - whole) * 10);
            var s = String(whole) + ((this._lang() === 'en') ? '.' : ',') + String(dec);
            return (v < 0 ? '-' : '') + s;
        }

        _r1(x) {
            return this._jsround(x * 10.0) / 10.0;
        }

        _r2(x) {
            return this._jsround(x * 100.0) / 100.0;
        }

        _fmtDec2(n) {
            var v = this._r2(n);
            var neg = v < 0;
            var cents = Math.round(Math.abs(v) * 100);
            var whole = Math.floor(cents / 100);
            var dec = cents - whole * 100;
            var s = String(whole) + ((this._lang() === 'en') ? '.' : ',') + (dec < 10 ? '0' : '') + String(dec);
            return (neg && cents > 0 ? '-' : '') + s;
        }

        _fmtPct1(n) {
            return this._fmtDec(n) + ((this._lang() === 'en') ? '%' : ' %');
        }

        _fmtMoney(n) {
            var v = Math.round(n);
            var body = this._fmtInt(Math.abs(v));
            if (this._lang() === 'en') { return (v < 0 ? '-' : '') + '€' + body; }
            return (v < 0 ? '-' : '') + body + ' €';
        }

        _sum(arr) {
            var s = 0, i;
            for (i = 0; i < arr.length; i++) { s += arr[i]; }
            return s;
        }

        _syncControlsFromDecisions(state) {
            var period = (state && state.currentPeriod) || 1;
            var d = (state && state.decisions) || {};
            var k = d['round' + period] || {};
            (this.CONTROLS[period] || []).forEach(function(key) {
                var el = document.getElementById(key);
                if (el && k[key]) { el.value = k[key]; }
            });
        }

        _set(id, text) {
            var el = document.getElementById(id);
            if (el) { el.textContent = text; }
        }

        _updateBriefing(state, forcedPeriod) {
            if (!state) { return; }
            var ds = state.domainState || {};
            var period = forcedPeriod || state.currentPeriod || 1;
            var done = !!ds.finished;
            var nameEl = document.getElementById('roundName');
            if (nameEl) {
                nameEl.textContent = done ? this._t('round_done')
                    : this._t((this.ROUNDS[period - 1] || this.ROUNDS[0]).nameKey);
            }
            var pH = ds.profitHistory || [];
            var cH = ds.cashHistory || [];
            var mH = ds.morosHistory || [];
            var dH = ds.docsHistory || [];
            var kH = ds.pmcHistory || [];
            var sH = ds.salesHistory || [];
            var n = pH.length;
            this._set('profitDisplay', n ? this._fmtMoney(pH[n - 1]) : '-');
            this._set('cashDisplay', n ? this._fmtMoney(cH[n - 1]) : '-');
            this._set('morosDisplay', n ? this._fmtPct1(mH[n - 1]) : '-');
            this._set('docsDisplay', n ? this._fmtPct1(dH[n - 1]) : '-');
            this._set('pmcDisplay', n ? (this._fmtInt(kH[n - 1]) + ' ' + this._t('unit_days')) : '-');
            this._set('salesDisplay', n ? this._fmtMoney(sH[n - 1]) : '-');
            var sc = (ds.performance && ds.performance.overallScore) || 0;
            this._set('scoreDisplay', String(sc));
            var i;
            for (i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) { panel.style.display = (!done && (i + 1) === period) ? '' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = done ? 'none' : ''; }
            this._syncControlsFromDecisions(state);
        }

        _fbKey(g, v) {
            var pfx = { precio1: 'pr', compras1: 'co', cobro2: 'cb', pago2: 'pg', aux3: 'ax', doc3: 'dc', moro4: 'mo', cierre4: 'ci' };
            var opts = {
                precio1: ['tarifa', 'bajo', 'alto', 'volumen'],
                compras1: ['mensual', 'campana', 'contado', 'semanal'],
                cobro2: ['contado', 'd30', 'd60', 'd90'],
                pago2: ['pronto', 'd30', 'd60', 'retrasar'],
                aux3: ['auxiliar', 'media', 'horas', 'nadie'],
                doc3: ['cotejo', 'recapitulativa', 'revision', 'ninguno'],
                moro4: ['reclamar', 'esperar', 'cortar', 'quita'],
                cierre4: ['conciliar', 'tal_cual', 'anular', 'enero']
            };
            var keys = {
                fb_pr_tarifa: 1, fb_pr_bajo: 1, fb_pr_alto: 1, fb_pr_volumen: 1,
                fb_co_mensual: 1, fb_co_campana: 1, fb_co_contado: 1, fb_co_semanal: 1,
                fb_cb_contado: 1, fb_cb_d30: 1, fb_cb_d60: 1, fb_cb_d90: 1,
                fb_pg_pronto: 1, fb_pg_d30: 1, fb_pg_d60: 1, fb_pg_retrasar: 1,
                fb_ax_auxiliar: 1, fb_ax_media: 1, fb_ax_horas: 1, fb_ax_nadie: 1,
                fb_dc_cotejo: 1, fb_dc_recapitulativa: 1, fb_dc_revision: 1, fb_dc_ninguno: 1,
                fb_mo_reclamar: 1, fb_mo_esperar: 1, fb_mo_cortar: 1, fb_mo_quita: 1,
                fb_ci_conciliar: 1, fb_ci_tal_cual: 1, fb_ci_anular: 1, fb_ci_enero: 1
            };
            if (!opts[g] || opts[g].indexOf(v) < 0) { return 'fb_next'; }
            var key = 'fb_' + pfx[g] + '_' + v;
            return keys[key] ? key : 'fb_next';
        }

        getHint(state, results) {
            var p = (results && results.period) || 1;
            var m = this._event(this._flat(state, p), p);
            var a = m.a;
            if (m.hard > 0) { return this._t('hint_cap'); }
            var ctl = this.CONTROLS[p] || [];
            var i;
            for (i = 0; i < ctl.length; i++) {
                if (a[ctl[i]] !== this.BEST[ctl[i]]) { return this._t(this._fbKey(ctl[i], a[ctl[i]])); }
            }
            return null;
        }

        getChartConfig() {
            return {
                profitChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Net profit', data: [], borderColor: '#1f5c8a', backgroundColor: 'rgba(31,92,138,0.12)', borderWidth: 2 }
                        ]
                    },
                    options: { responsive: true }
                },
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Round score', data: [], borderColor: '#1f5c8a', backgroundColor: 'rgba(31,92,138,0.35)', borderWidth: 1 },
                            { label: 'Correct documents', data: [], borderColor: '#2f6b3a', backgroundColor: 'rgba(47,107,58,0.30)', borderWidth: 1 }
                        ]
                    },
                    options: { responsive: true, scales: { y: { beginAtZero: true, max: 100 } } }
                }
            };
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var profitHistory = ds.profitHistory || [];
            var docsHistory = ds.docsHistory || [];
            var scoreHistory = ds.scoreHistory || [];
            var self = this;
            var labels = profitHistory.map(function(x, i) { return self._t('round_label_short') + (i + 1); });
            return {
                profitChart: {
                    labels: labels,
                    datasets: [
                        { data: profitHistory.slice(), label: this._t('chart_profit') }
                    ]
                },
                scoreChart: {
                    labels: scoreHistory.map(function(x, i) { return self._t('round_label_short') + (i + 1); }),
                    datasets: [
                        { data: scoreHistory.slice(), label: this._t('chart_score') },
                        { data: docsHistory.slice(), label: this._t('chart_docs') }
                    ]
                }
            };
        }

        getHistoryTableConfig() {
            var self = this;
            var pct1 = function(v) { return self._fmtPct1(v); };
            var money = function(v) { return self._fmtMoney(v); };
            var intf = function(v) { return self._fmtInt(v); };
            return [
                { key: 'results.profit', label: 'Net profit', i18nKey: 'col_profit', formatter: money },
                { key: 'results.cash', label: 'Cash at 31-12', i18nKey: 'col_cash', formatter: money },
                { key: 'results.moros', label: 'Morosidad (%)', i18nKey: 'col_moros', formatter: pct1 },
                { key: 'results.docs', label: 'Correct documents (%)', i18nKey: 'col_docs', formatter: pct1 },
                { key: 'results.pmc', label: 'Days sales outstanding', i18nKey: 'col_pmc', formatter: intf },
                { key: 'results.sales', label: 'Sales', i18nKey: 'col_sales', formatter: money },
                { key: 'results.roundScore', label: 'Round score', i18nKey: 'col_score' }
            ];
        }

        getPerformanceSummary(history) {
            var state = window.mySimulation.state;
            var n = this._completed(state);
            var mm = Math.max(1, n);
            var d = this._flat(state, mm);
            var m = this._event(d, mm);
            var kp = this._kpis(m);
            var composite = this._composite(state);
            var insights = [];
            var self = this;
            var shown = this.KEYS.filter(function(g) { return self.ROUND_OF[g] <= mm; });
            shown.forEach(function(g) { insights.push(self._t(self._fbKey(g, self._active(d, mm, g)))); });
            if (m.hard > 0) { insights.push(this._t('cm_cap')); }
            insights.push(this._t('fb_next'));
            var vk = this._verdictKey(composite);
            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                performance: vk.replace('verdict_', ''),
                performanceLabel: this._t(vk),
                sales: kp.sales,
                profit: kp.profit,
                cash: kp.cash,
                moros: kp.moros,
                docs: kp.docs,
                pmc: kp.pmc,
                stuck: Math.round(m.stuck),
                acOpen: Math.round(m.acOpen),
                err: Math.round(m.err),
                hard: m.hard,
                periods: (history || []).length,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var items = (s.insights || []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
            return '<div class="ej2702-cm">'
                + '<div class="ej2702-cm-score">' + score + '<span class="ej2702-cm-max">/100</span></div>'
